// TestPackLane is the spec floor for "Pack lane — remux-only fMP4-HLS with
// atomic build-nonce publish" (probe f9e6ec5d9a440008): a packaged artifact is
// published under a fresh nonce, stream-copy only (no subtitle track survives),
// playlists and segments land, a repack never collides, and the arg builders
// carry exactly the locked flags.
func TestPackLane(t *testing.T) {
	ctx := context.Background()

	t.Run("remux_publishes_fmp4_hls", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second) // head 5s + tail 7s: both phases run
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

		build, err := s.Pack(ctx, "it1", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		if !strings.HasPrefix(build.Playlist, "/media/it1/") || !strings.HasSuffix(build.Playlist, "/index.m3u8") {
			t.Fatalf("Build.Playlist = %q, want /media/it1/<nonce>/index.m3u8", build.Playlist)
		}
		if build.Nonce == "" || !strings.Contains(build.Playlist, build.Nonce) {
			t.Fatalf("Build = %+v: playlist and nonce must agree", build)
		}
		buildDir := filepath.Join(s.Root, "it1", build.Nonce)

		play, err := os.ReadFile(filepath.Join(buildDir, "index.m3u8"))
		if err != nil {
			t.Fatalf("published playlist: %v", err)
		}
		pl := string(play)
		for _, want := range []string{"#EXTM3U", "#EXT-X-ENDLIST", "#EXT-X-DISCONTINUITY", "init.mp4", "t/"} {
			if !strings.Contains(pl, want) {
				t.Fatalf("published playlist missing %q:\n%s", want, pl)
			}
		}
		if _, err := os.Stat(filepath.Join(buildDir, "init.mp4")); err != nil {
			t.Fatalf("head init segment missing: %v", err)
		}
		if n := countPrefix(pl, "seg-"); n < 2 {
			t.Fatalf("playlist names %d segments, want head and tail segments:\n%s", n, pl)
		}

		// Stream-copy only: the published init segment carries the fixture's
		// video + audio and NO subtitle track (-sn dropped it).
		kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "init.mp4")))
		if kinds["video"] != 1 || kinds["audio"] < 1 {
			t.Fatalf("init.mp4 streams = %v, want 1 video + audio", kinds)
		}
		if kinds["subtitle"] != 0 {
			t.Fatalf("init.mp4 carries %d subtitle streams; the pack lane must drop them (-sn)", kinds["subtitle"])
		}
		// The whole published playlist probes as playable media.
		kinds = streamKinds(probeStreams(t, buildDir+"/index.m3u8"))
		if kinds["video"] != 1 || kinds["audio"] < 1 || kinds["subtitle"] != 0 {
			t.Fatalf("published playlist streams = %v, want remuxed media only", kinds)
		}
	})

	t.Run("whole_file_within_head_chunk_finalizes_without_tail", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // default head

		build, err := s.Pack(ctx, "it_short", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "it_short", build.Nonce)
		pl := readFile(t, filepath.Join(buildDir, "index.m3u8"))
		if strings.Contains(pl, "#EXT-X-DISCONTINUITY") {
			t.Fatalf("short file ran a tail phase (spurious discontinuity):\n%s", pl)
		}
		if !strings.Contains(pl, "#EXT-X-ENDLIST") {
			t.Fatalf("short file playlist missing ENDLIST:\n%s", pl)
		}
		if _, err := os.Stat(filepath.Join(buildDir, "t")); err == nil {
			t.Fatal("tail directory published for a short file")
		}
	})

	t.Run("repack_publishes_fresh_nonce_and_keeps_old_bytes", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second)

		b1, err := s.Pack(ctx, "it2", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack 1: %v", err)
		}
		oldBytes := readFile(t, filepath.Join(s.Root, "it2", b1.Nonce, "index.m3u8"))
		b2, err := s.Pack(ctx, "it2", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack 2: %v", err)
		}
		if b2.Nonce == b1.Nonce {
			t.Fatalf("repack reused nonce %s; builds must never collide (D-5)", b1.Nonce)
		}
		if got := readFile(t, filepath.Join(s.Root, "it2", b1.Nonce, "index.m3u8")); got != oldBytes {
			t.Fatal("first build's playlist bytes changed when a second build published")
		}
	})

	t.Run("missing_ffmpeg_fails_with_nothing_published", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		root := filepath.Join(dir, "streams")
		s := newTestService(t, root, 600*time.Second)
		s.FFmpeg = filepath.Join(dir, "no-such-ffmpeg") // LookPath fails

		if _, err := s.Pack(ctx, "it3", fixture, nil, nil); err == nil {
			t.Fatal("Pack succeeded without ffmpeg; want an error")
		}
		// Nothing published: no playlist anywhere under the artifact root
		// (a transient tmp directory may exist, but nothing is referenceable).
		_ = filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
			if err == nil && !d.IsDir() && strings.HasSuffix(p, ".m3u8") {
				t.Errorf("failed pack published %s", p)
			}
			return nil
		})
	})

	t.Run("arg_builders_carry_the_locked_flags", func(t *testing.T) {
		dir := "/out"
		cases := []struct {
			name    string
			args    []string
			seekTo  bool // tail: -ss before -i
			limitTo bool // head: -t duration cap
		}{
			{"head", packHeadArgs("/in/f.mkv", nil, 600*time.Second, 4*time.Second, dir), false, true},
			{"tail", packTailArgs("/in/f.mkv", nil, 600*time.Second, 4*time.Second, dir), true, false},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				joined := strings.Join(tc.args, "\x00")
				for _, want := range []string{
					"-nostdin", "\x00-i\x00", "-map\x000:v:0", "-map\x000:a",
					"-sn\x00-dn", "-c\x00copy", "-f\x00hls",
					"-hls_segment_type\x00fmp4",
				} {
					if !strings.Contains(joined, want) {
						t.Fatalf("args missing %q: %q", want, joined)
					}
				}
				for _, banned := range []string{"libx264", "-c:v", "-vf", "-c:a", "aac", "sh", "-c"} {
					if banned == "-c" {
						continue // covered above as an exact "-c copy" pair
					}
					if strings.Contains(joined, banned) {
						t.Fatalf("args carry encoder/transform flag %q (remux only): %q", banned, joined)
					}
				}
				if tc.seekTo {
					if !strings.Contains(joined, "-ss\x00600.000\x00-i") {
						t.Fatalf("tail args missing -ss before -i: %q", joined)
					}
					if strings.Contains(joined, "omit_endlist") {
						t.Fatal("tail args must not omit ENDLIST")
					}
				}
				if tc.limitTo {
					if !strings.Contains(joined, "-t\x00600.000") {
						t.Fatalf("head args missing -t cap: %q", joined)
					}
					if !strings.Contains(joined, "omit_endlist") {
						t.Fatal("head args must omit ENDLIST (partial EVENT playlist)")
					}
				}
			})
		}
	})
}

// countPrefix counts playlist URI entries whose name starts with prefix.
func countPrefix(playlist, prefix string) int {
	n := 0
	for _, line := range strings.Split(playlist, "\n") {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") && strings.Contains(filepath.Base(line), prefix) {
			n++
		}
	}
	return n
}

// readFile reads a file or fails the test.
func readFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return string(b)
}

// TestHeadFirst is the spec floor for "Head-first partial packaging" (probe
// 750761395b927c06): the first chunk is published playable BEFORE the
// remainder packages (an EVENT playlist with no ENDLIST is observable at the
// hook), and on completion the playlist is the grown, ENDLIST-terminated build.
func TestHeadFirst(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	fixture := makeFixture(t, dir, 12*time.Second)
	s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

	var headPlaylist string
	s.afterHead = func(p string) {
		pl := readFile(t, p)
		headPlaylist = pl
		if strings.Contains(pl, "#EXT-X-ENDLIST") {
			t.Errorf("head-phase playlist already ended (no live partial):\n%s", pl)
		}
		if n := countPrefix(pl, "seg-"); n == 0 {
			t.Errorf("head-phase playlist names no segments (nothing playable):\n%s", pl)
		}
	}

	build, err := s.Pack(ctx, "it_hf", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
	if err != nil {
		t.Fatalf("Pack: %v", err)
	}
	if headPlaylist == "" {
		t.Fatal("afterHead hook never fired — the head phase was not observed mid-run")
	}
	final := readFile(t, filepath.Join(s.Root, "it_hf", build.Nonce, "index.m3u8"))
	if !strings.Contains(final, "#EXT-X-ENDLIST") {
		t.Fatalf("completed build missing ENDLIST:\n%s", final)
	}
	if strings.Count(final, "seg-") <= strings.Count(headPlaylist, "seg-") {
		t.Fatalf("final playlist did not grow past the head phase (head %d, final %d segment URIs)",
			strings.Count(headPlaylist, "seg-"), strings.Count(final, "seg-"))
	}
	if !strings.Contains(final, "#EXT-X-DISCONTINUITY") {
		t.Fatalf("final playlist missing the tail splice discontinuity:\n%s", final)
	}
}

// TestHeadOnlySegmentsPublished pins the whole-file-within-head-chunk publish
// (probe 3694483270be0ea8): the legacy single-variant head-only build publishes
// its segments WITH the playlist — the playlist is finalized inside tmp and the
// whole directory renames into place, so Pack's tmp cleanup cannot strand the
// segments behind a published playlist. After Pack, every reference in the
// published playlist must resolve relative to the playlist's own directory
// (how hls.js resolves playlist URIs) and every published segment must be
// listed — the same two assertions the tail-window repro pins for the tail lane.
func TestHeadOnlySegmentsPublished(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	fixture := makeFixture(t, dir, 12*time.Second)
	s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // default head: the whole file IS the head chunk

	build, err := s.Pack(ctx, "it_head_only", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
	if err != nil {
		t.Fatalf("Pack: %v", err)
	}
	buildDir := filepath.Join(s.Root, "it_head_only", build.Nonce)
	playlistPath := filepath.Join(buildDir, "index.m3u8")
	pl := readFile(t, playlistPath)
	if !strings.Contains(pl, "#EXT-X-ENDLIST") {
		t.Fatalf("head-only playlist missing ENDLIST:\n%s", pl)
	}
	if strings.Contains(pl, "#EXT-X-DISCONTINUITY") {
		t.Fatalf("head-only playlist ran a tail phase (spurious discontinuity):\n%s", pl)
	}

	// playlistRefs returns the referenced URIs of a media playlist: every
	// non-tag line (segment URIs) plus every EXT-X-MAP URI="..." attribute.
	var refs []string
	for _, line := range strings.Split(pl, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			if strings.HasPrefix(line, "#EXT-X-MAP") {
				if i := strings.Index(line, `URI="`); i >= 0 {
					rest := line[i+len(`URI="`):]
					if j := strings.Index(rest, `"`); j >= 0 {
						refs = append(refs, rest[:j])
					}
				}
			}
			continue
		}
		refs = append(refs, line)
	}
	if len(refs) == 0 {
		t.Fatalf("head-only playlist references nothing (nothing playable):\n%s", pl)
	}
	// REACHABILITY — every ref must exist relative to the playlist dir.
	for _, ref := range refs {
		if _, err := os.Stat(filepath.Join(buildDir, ref)); err != nil {
			t.Errorf("playlist references %q: not found relative to the playlist dir (player 404)", ref)
		}
	}
	// COVERAGE — the playlist lists every segment published under the build
	// dir (a whole-file build has no t/ tree; everything is a head segment).
	onDisk := 0
	entries, err := os.ReadDir(buildDir)
	if err != nil {
		t.Fatalf("build dir: %v", err)
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasPrefix(e.Name(), "seg-") {
			onDisk++
		}
	}
	listed := 0
	for _, ref := range refs {
		if strings.HasPrefix(filepath.Base(ref), "seg-") {
			listed++
		}
	}
	if listed != onDisk {
		t.Errorf("playlist lists %d segments but %d were published under %s: the head-only publish stranded segments",
			listed, onDisk, buildDir)
	}
}
